/**
 * Playes the scared Animation.
 * @param {Array} styles References to the styles of all parts of the character
 * @param {Object} characterInfo the Information about the character generated by the CharacterInfoLoader
 */
export function animationScared(styles, characterInfo) {
  const maxRad = 10;
  const duration = 100;
  const speedFactor = 0.2;
  const radDecreaseFactor = 1.03
  let frame = 0;
  const animate = () => {
    styles.forEach(style => {
      style.left = `${characterInfo["positionX"] - maxRad * Math.cos(speedFactor * frame)/Math.pow(radDecreaseFactor, frame)}cqw`;
      style.top = `${characterInfo["positionY"] + maxRad * Math.sin(speedFactor * frame)/Math.pow(radDecreaseFactor, frame)}cqw`;
    });
    if((++frame) <= duration) {
      requestAnimationFrame(animate)
    }
    else {
      // Reset to derfault values
      styles.forEach(style => {
        style.left = `${characterInfo["positionX"]}cqw`;
        style.top = `${characterInfo["positionY"]}cqw`;
      });
    }

  }
  requestAnimationFrame(animate);
}